const envelope = $input.first()?.json ?? {};
const payload = envelope.body ?? envelope;
const message = payload.message ?? {};
const call = payload.call ?? message.call ?? {};
const artifact = payload.artifact ?? message.artifact ?? call.artifact ?? {};
const variables = artifact.variableValues ?? message.variableValues ?? call.assistantOverrides?.variableValues ?? {};
const config = {
  max_transcript_characters: 12000,
  llm_enabled: false,
  llm_endpoint: 'https://replace.example/v1/structured-call-analysis',
  llm_model: 'configure-in-provider',
  crm_enabled: false,
  hubspot_base_url: 'https://api.hubapi.com',
  metrics_sink_enabled: false,
  metrics_sink_url: 'https://replace.example/api/call-metrics'
};
const redact = (value) => String(value ?? '')
  .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[EMAIL_REDACTED]')
  .replace(/\+?\d[\d\s().-]{7,}\d/g, '[PHONE_REDACTED]')
  .replace(/\b(?:\d[ -]*?){13,19}\b/g, '[NUMBER_REDACTED]');
const stableHash = (value) => {
  let hash = 2166136261;
  for (const character of String(value ?? '')) {
    hash ^= character.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return value ? (hash >>> 0).toString(36) : null;
};
const callId = String(payload.call_id ?? call.id ?? message.callId ?? '');
const eventType = String(payload.event_type ?? message.type ?? 'post-call');
const callStatus = String(payload.call_status ?? message.status ?? call.status ?? 'ended');
const endedReason = String(payload.ended_reason ?? message.endedReason ?? call.endedReason ?? '');
const transcript = redact(payload.transcript ?? artifact.transcript ?? '').slice(0, config.max_transcript_characters);
const sourceMessages = Array.isArray(payload.messages) ? payload.messages : (Array.isArray(artifact.messages) ? artifact.messages : []);
const messages = sourceMessages.slice(-100).map((entry) => ({
  role: ['assistant', 'user', 'system'].includes(entry.role) ? entry.role : 'unknown',
  message: redact(entry.message ?? entry.content ?? '').slice(0, 2000)
}));
const startedAt = payload.started_at ?? call.startedAt ?? null;
const endedAt = payload.ended_at ?? call.endedAt ?? null;
const durationSeconds = Number(payload.duration_seconds ?? call.durationSeconds ?? 0);
const callerHash = payload.caller_hash ?? stableHash(call.customer?.number ?? message.customer?.number ?? '');
const contactRef = String(payload.contact_ref ?? variables.contact_ref ?? '');
const hubspotContactId = String(payload.hubspot_contact_id ?? variables.hubspot_contact_id ?? '');
const state = $getWorkflowStaticData('global');
state.processedPostCalls ??= {};
const duplicate = Boolean(callId && state.processedPostCalls[callId]);
const finalSignal = eventType === 'end-of-call-report' || eventType === 'outbound-status-poll' || callStatus === 'ended' || Boolean(endedAt) || Boolean(endedReason);
const valid = Boolean(callId && finalSignal);
const processRoute = !valid ? 'invalid' : (duplicate ? 'duplicate' : 'process');
return [{ json: {
  config,
  valid,
  duplicate,
  process_route: processRoute,
  validation_errors: [!callId ? 'missing-call-id' : null, !finalSignal ? 'not-a-final-call-record' : null].filter(Boolean),
  event_type: eventType,
  call_id: callId,
  call_status: callStatus,
  call_direction: String(payload.call_direction ?? call.type ?? 'unknown'),
  ended_reason: endedReason || null,
  started_at: startedAt,
  ended_at: endedAt,
  duration_seconds: durationSeconds,
  transcript,
  messages,
  recording_present: Boolean(payload.recording_present ?? artifact.recording),
  caller_hash: callerHash,
  contact_ref: contactRef || null,
  hubspot_contact_id: hubspotContactId || null,
  received_at: new Date().toISOString()
} }];

const state = $getWorkflowStaticData('global');
state.postCallAudit ??= [];
state.postCallAudit.push({
  at: new Date().toISOString(),
  event: $json.duplicate ? 'duplicate-post-call-ignored' : 'invalid-post-call-rejected',
  call_id: $json.call_id || null,
  caller_hash: $json.caller_hash || null,
  errors: $json.validation_errors || []
});
state.postCallAudit = state.postCallAudit.slice(-500);
return [{ json: { processed: false, route: $json.process_route, call_id: $json.call_id || null } }];

const messages = Array.isArray($json.messages) ? $json.messages : [];
const userTurns = messages.filter((entry) => entry.role === 'user').length;
const assistantTurns = messages.filter((entry) => entry.role === 'assistant').length;
const transcript = String($json.transcript ?? '');
const lower = transcript.toLowerCase();
let duration = Number($json.duration_seconds ?? 0);
if (!duration && $json.started_at && $json.ended_at) {
  duration = Math.max(0, Math.round((new Date($json.ended_at).getTime() - new Date($json.started_at).getTime()) / 1000));
}
let outcome = 'unknown';
if (($json.ended_reason || '').toLowerCase().includes('voicemail') || /leave (?:a )?message|after the tone|voicemail/.test(lower)) outcome = 'voicemail';
else if (/appointment (?:is )?(?:booked|confirmed)|meeting (?:is )?(?:booked|confirmed)|scheduled for/.test(lower)) outcome = 'booked';
else if (/call (?:me|us) back|callback|try again (?:later|tomorrow)/.test(lower)) outcome = 'callback-requested';
else if (/not interested|do not call|remove me|stop calling/.test(lower)) outcome = 'not-interested';
else if (transcript.length > 0) outcome = 'completed';
const summarySource = transcript.replace(/\s+/g, ' ').trim();
const fallbackSummary = summarySource ? `${summarySource.slice(0, 420)}${summarySource.length > 420 ? '…' : ''}` : `Call ended with status ${$json.call_status}.`;
const actionMap = {
  booked: ['Confirm the appointment details and owner.'],
  'callback-requested': ['Create a time-bound callback task.'],
  'not-interested': ['Apply the appropriate suppression or nurture status.'],
  voicemail: ['Follow the approved voicemail follow-up policy.'],
  completed: ['Review the summary and assign the next owner.'],
  unknown: ['Review the call record manually.']
};
const deterministicAnalysis = {
  outcome,
  summary: fallbackSummary,
  action_items: actionMap[outcome] ?? actionMap.unknown,
  confidence: outcome === 'unknown' ? 0.25 : 0.65
};
return [{ json: {
  ...$json,
  duration_seconds: duration,
  user_turn_count: userTurns,
  assistant_turn_count: assistantTurns,
  total_turn_count: userTurns + assistantTurns,
  deterministic_analysis: deterministicAnalysis,
  analysis_route: $json.config.llm_enabled && transcript.length > 0 ? 'llm' : 'deterministic'
} }];

const base = $node['Compute Deterministic Call Metrics'].json;
const response = $json ?? {};
let candidate = response.output_text ?? response.data?.output ?? response.result ?? response.choices?.[0]?.message?.content ?? null;
if (candidate && typeof candidate === 'object') candidate = candidate;
else if (typeof candidate === 'string') {
  const cleaned = candidate.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  try { candidate = JSON.parse(cleaned); } catch { candidate = null; }
}
const allowed = new Set(['booked', 'callback-requested', 'not-interested', 'voicemail', 'completed', 'unknown']);
const valid = candidate && typeof candidate === 'object' && allowed.has(candidate.outcome) && typeof candidate.summary === 'string';
const analysis = valid ? {
  outcome: candidate.outcome,
  summary: candidate.summary.replace(/\s+/g, ' ').trim().slice(0, 500),
  action_items: Array.isArray(candidate.action_items) ? candidate.action_items.filter((value) => typeof value === 'string').slice(0, 5).map((value) => value.slice(0, 180)) : [],
  confidence: Math.max(0, Math.min(1, Number(candidate.confidence ?? 0.5)))
} : base.deterministic_analysis;
return [{ json: { ...base, analysis, llm_used: Boolean(valid), llm_parse_fallback: !valid } }];

const analysis = $json.analysis ?? $json.deterministic_analysis;
const endedAt = $json.ended_at ?? $json.received_at;
const actionLines = (analysis.action_items || []).map((item) => `- ${item}`).join('\n') || '- Manual review';
const noteText = [
  'JavedAI voice call result',
  `Outcome: ${analysis.outcome}`,
  `Duration: ${$json.duration_seconds} seconds`,
  `Summary: ${analysis.summary}`,
  'Next actions:',
  actionLines,
  `Vapi call ID: ${$json.call_id}`
].join('\n');
const hubspotContactUpdateBody = { properties: {
  javedai_last_call_outcome: analysis.outcome,
  javedai_last_call_summary: analysis.summary,
  javedai_last_call_at: endedAt,
  javedai_last_vapi_call_id: $json.call_id
} };
const hubspotNoteBody = {
  properties: { hs_timestamp: endedAt, hs_note_body: noteText },
  associations: [{
    to: { id: $json.hubspot_contact_id },
    types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 202 }]
  }]
};
const metricEvent = {
  event: 'call-analysis-completed',
  at: new Date().toISOString(),
  call_id: $json.call_id,
  direction: $json.call_direction,
  status: $json.call_status,
  ended_reason: $json.ended_reason,
  outcome: analysis.outcome,
  confidence: analysis.confidence,
  duration_seconds: $json.duration_seconds,
  user_turn_count: $json.user_turn_count,
  assistant_turn_count: $json.assistant_turn_count,
  total_turn_count: $json.total_turn_count,
  recording_present: $json.recording_present,
  caller_hash: $json.caller_hash,
  contact_ref: $json.contact_ref,
  llm_used: $json.llm_used
};
return [{ json: {
  ...$json,
  hubspot_contact_update_body: hubspotContactUpdateBody,
  hubspot_note_body: hubspotNoteBody,
  metric_event: metricEvent,
  crm_route: $json.config.crm_enabled && Boolean($json.hubspot_contact_id) ? 'update' : 'skip'
} }];

const base = $node['Build CRM and Metric Payload'].json;
return [{ json: {
  config: base.config,
  call_id: base.call_id,
  caller_hash: base.caller_hash,
  metric_event: { ...base.metric_event, crm_attempted: base.crm_route === 'update' },
  metrics_route: base.config.metrics_sink_enabled ? 'send' : 'local-only'
} }];

const metricRecord = $node['Finalize Sanitized Metric Event'].json;
const state = $getWorkflowStaticData('global');
state.processedPostCalls ??= {};
state.postCallAudit ??= [];
state.processedPostCalls[metricRecord.call_id] = new Date().toISOString();
state.postCallAudit.push(metricRecord.metric_event);
state.postCallAudit = state.postCallAudit.slice(-500);
const cutoff = Date.now() - (35 * 24 * 60 * 60 * 1000);
for (const [callId, timestamp] of Object.entries(state.processedPostCalls)) {
  if (new Date(timestamp).getTime() < cutoff) delete state.processedPostCalls[callId];
}
return [{ json: { processed: true, call_id: metricRecord.call_id, outcome: metricRecord.metric_event.outcome, metrics_external: metricRecord.metrics_route === 'send' } }];
